  ],
  "claims": [
    {
      "claim": "The query is stavudine (d4T), a thymine 2',3'-didehydro-2',3'-dideoxynucleoside. Closely related pyrimidine dideoxynucleosides have measured absolute oral bioavailability well above 20%: emtricitabine 92% fasted and 93% in multiple reports, lamivudine 68.6–93% across formulations, and zalcitabine 80% (54–127%) in humans; even the less bioavailable nucleoside cladribine is 36–46%.",
      "card_ids": ["C19","C31","C01","C05","C10","C13","C04","C06","C15","C20","C23","C24","C17","C07","C12","C16","C18"]
    },
    {
      "claim": "L4 intestinal absorption records show that AZT, which shares the thymine base, has a human fraction absorbed of 98% and >90% gastrointestinal absorption at 60 mg/kg in an animal study; thymine solubility in FeSSIF is 6.2 ± 0.2 mg/mL, supporting adequate dissolution for this low-logD nucleoside scaffold.",
      "card_ids": ["C55","C45","C52"]
    },
    {
      "claim": "L3 lamivudine oral exposure records show rapid absorption (median Tmax 0.75–1.26 h) and measurable Cmax after oral dosing, consistent with high oral bioavailability in this nucleoside class.",
      "card_ids": ["C33","C36","C42"]
    },
    {
      "claim": "L5 gut-wall/intestinal records classify AZT as high permeability (P_eff 4.17 ± 0.43 × 10^-5 cm/s) and lamivudine as moderate-to-high permeability (P_eff 3.08 ± 0.26 × 10^-5 cm/s); no supplied record provides affirmative gut-wall efflux or intestinal-metabolism evidence for F < 20% for stavudine.",
      "card_ids": ["C56","C58","C65","C61"]
    },
    {
      "claim": "Didanosine's low/variable F (0.22–0.28, 29 ± 6%, <40%, range 2–89%) is formulation- and acid-lability-dependent and is not transferable to stavudine; the single mouse zalcitabine value of 30% is species-limited and outweighed by the human value of 80%.",
      "card_ids": ["C03","C09","C11","C14","C25","C27","C28","C17"]
    },
    {
      "claim": "L6 hepatic-clearance records concern AZT (3'-azido-3'-deoxythymidine) and 5-ethyl-AzddU, not stavudine. AZT has substantial UGT-mediated hepatic clearance (in vivo 19 ml/min/kg; hepatocyte-scaled 15.1 ml/min/kg) and 5-ethyl-AzddU is a UDPGT substrate, but stavudine lacks the 3'-azido group and no stavudine-specific hepatic-clearance or metabolic-stability measurement is supplied; these records do not provide affirmative evidence for F < 20% for stavudine.",
      "card_ids": ["C68","C69","C70","C71","C72","C73","C74","C75","C76","C77","C78","C79"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C68","C69","C70","C71","C72","C73","C74","C75","C76","C77","C78","C79"]
    }
  ],
  "evidence_gaps": [
    "No direct stavudine absolute-bioavailability record is present; prediction relies on structural transfer from closely related pyrimidine dideoxynucleosides and AZT.",
    "No query-specific IV comparison, AUC, Cmax, dose, or formulation data are supplied.",
    "No stavudine-specific hepatic clearance or metabolic-stability measurement is available; L6 AZT/5-ethyl-AzddU records are not directly transferable.",
    "Food effects and first-pass metabolic/clearance contributions for stavudine are not directly measured in the cited records.",
    "Didanosine's low/variable F is formulation- and acid-sensitivity-dependent and is not treated as transferable negative evidence."
  ],
  "decision_summary": "High: stavudine is a thymine dideoxynucleoside closely related to emtricitabine, lamivudine, and zalcitabine, all with measured absolute oral bioavailability well above 20%; L4/L5 absorption and permeability records support efficient intestinal absorption; L6 hepatic-clearance records are for AZT/5-ethyl-AzddU and are not transferable to stavudine, so they do not provide affirmative evidence for F < 20%."
}

